sys_script_client.script:
function onLoad() {
   var currentUser = g_user.getUserID();
   var currentUserName = g_user.getUserName();
   g_form.setValue('opened_by',currentUser);
   g_form.setReadOnly('opened_by',true);

   var ga = new GlideAjax('GetUserProject'); 
   ga.addParam('sysparm_name','getProjectByUser');
   ga.addParam('sysparm_user', currentUser);
   ga.getXML(callback);

   function callback(response){
	var answer = response.responseXML.documentElement.getAttribute("answer");
	if (answer){
		var projectInfo = answer.split(','); 
		var projectSysId = 	projectInfo[0];
		var projectName = projectInfo[1];

		g_form.setValue('project_id',projectSysId);
		g_form.setReadOnly('project_id',true);
	}

   }


}
